-- Idempotent PostgreSQL script for Payment Methods
DO $$ 
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_name = 'Orders') THEN
        RAISE EXCEPTION 'PaymentMethods.sql must run against pos_db after Orders table exists';
    END IF;
END $$;

CREATE TABLE IF NOT EXISTS "PaymentMethods" (
    "payment_method_id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "code" VARCHAR(30) UNIQUE NOT NULL,
    "name" VARCHAR(100) NOT NULL,
    "requires_reference" BOOLEAN NOT NULL DEFAULT false,
    "is_active" BOOLEAN NOT NULL DEFAULT true,
    "display_order" INT NOT NULL DEFAULT 0
);

-- Seed standard commercial POS payment methods
INSERT INTO "PaymentMethods" ("code", "name", "requires_reference", "is_active", "display_order")
VALUES 
    ('CASH', 'Cash', false, true, 1),
    ('CARD', 'Visa / Mastercard', true, true, 2),
    ('GCASH', 'GCash E-Wallet', true, true, 3),
    ('MAYA', 'Maya E-Wallet', true, true, 4)
ON CONFLICT ("code") DO UPDATE 
SET 
    "name" = EXCLUDED."name",
    "requires_reference" = EXCLUDED."requires_reference",
    "is_active" = EXCLUDED."is_active",
    "display_order" = EXCLUDED."display_order";
